 6	final class KahnTopologicalSorter implements TopologicalSorter {
 7	    @Override
 8	    public List<Integer> sort(DirectedGraph graph) {
 9	        int[] indegree = buildIndegreeTable(graph);
10	        Deque<Integer> readyVertices = collectZeroIndegreeVertices(indegree);
11	        List<Integer> order = new ArrayList<>(graph.vertexCount());
12	
13	        while (!readyVertices.isEmpty()) {
14	            int vertex = readyVertices.removeFirst();
15	            order.add(vertex);
16	            for (int next : graph.neighborsOf(vertex)) {
17	                indegree[next]--;
18	                if (indegree[next] == 0) {
19	                    readyVertices.addLast(next);
20	                }
21	            }
22	        }
23	
24	        validateAcyclic(graph, order);
25	        return order;
26	    }
27	
28	    private int[] buildIndegreeTable(DirectedGraph graph) {
29	        int[] indegree = new int[graph.vertexCount()];
30	        for (int vertex = 0; vertex < graph.vertexCount(); vertex++) {
31	            for (int neighbor : graph.neighborsOf(vertex)) {
32	                indegree[neighbor]++;
33	            }
34	        }
35	        return indegree;
36	    }
37	
38	    private Deque<Integer> collectZeroIndegreeVertices(int[] indegree) {
39	        Deque<Integer> readyVertices = new ArrayDeque<>();
40	        for (int vertex = 0; vertex < indegree.length; vertex++) {
41	            if (indegree[vertex] == 0) {
42	                readyVertices.addLast(vertex);
43	            }
44	        }
45	        return readyVertices;
46	    }
47	
48	    private void validateAcyclic(DirectedGraph graph, List<Integer> order) {
49	        if (order.size() != graph.vertexCount()) {
50	            throw new IllegalStateException("Topological sort requires a directed acyclic graph.");
51	        }
52	    }
53	}

